   139	/**
   140	 * Converts a color in hexadecimal notation into RGB notation.
   141	 *
   142	 * @param hexadecimal A color in hexadecimal notation.
   143	 * @returns `undefined` if the input color is not in hexadecimal notation. Otherwise, the RGB components of the input color.
   144	 */
   145	function hexadecimalToRGBArray(hexadecimal: string): number[] | undefined {
   146	    const components = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hexadecimal);
   147	
   148	    if (components === null) {
   149	        return undefined;
   150	    }
   151	
   152	    return components.slice(1).map((component) => parseInt(component, 16));
   153	}
