   155	/**
   156	 * Converts a color in RGBA notation to an equivalent color in RGB notation.
   157	 *
   158	 * @param foregroundRGB The three components of the foreground color in RGB notation.
   159	 * @param backgroundRGB The three components of the background color in RGB notation.
   160	 * @param opacity The desired opacity of the foreground color.
   161	 * @returns The RGB components of the RGBA color converted to RGB.
   162	 */
   163	function convertRGBAToRGB(foregroundRGB: number[], backgroundRGB: number[], opacity: number): number[] {
   164	    const [foregroundRed, foregroundGreen, foregroundBlue] = foregroundRGB;
   165	    const [backgroundRed, backgroundGreen, backgroundBlue] = backgroundRGB;
   166	
   167	    return [(1 - opacity) * backgroundRed + opacity * foregroundRed, (1 - opacity) * backgroundGreen + opacity * foregroundGreen, (1 - opacity) * backgroundBlue + opacity * foregroundBlue];
   168	}
