   173	 * @param red A unit value representing the first component of a color in RGB notation.
   174	 * @param green A unit value representing the second component of a color in RGB notation.
   175	 * @param blue A unit value representing the third component of a color in RGB notation.
   176	 * @returns An array with the three components of a color in RGB notation.
   177	 */
   178	function convertUnitValuesToRGB(red: number, green: number, blue: number): number[] {
   179	    return [Math.floor(red * 255), Math.floor(green * 255), Math.floor(blue * 255)];
